package com.bank.kthlargest;

import java.util.*;
import java.util.logging.*;

public class KthLargestDemo {
    private static final Logger log = Logger.getLogger("KthLargest");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> amounts = List.of(5000, 20000, 20000, 15000, 8000, 12000);
        KthLargestService service = new KthLargestService();

        log.info(() -> "3rd largest distinct: " + service.kthLargest(amounts, 3).orElse(-1));
        log.info(() -> "10th (out of range) : " + service.kthLargest(amounts, 10).orElse(-1));
    }
}

// ─── Would be in service/KthLargestService.java ───
class KthLargestService {
    Optional<Integer> kthLargest(List<Integer> nums, int k) {
        if (k < 1) return Optional.empty();
        return nums.stream()
            .distinct()                              // distinct ranks
            .sorted(Comparator.reverseOrder())        // descending
            .skip(k - 1L)                             // drop top k-1
            .findFirst();                             // → kth largest
    }
}
